/**
 * Helper to get list of thanas for a given district name
 */
export function getThanasForDistrict(districtName) {
  if (!districtName) return [];
  const clean = String(districtName).trim();
  
  // Direct match
  if (THANAS_BY_DISTRICT[clean]) {
    return THANAS_BY_DISTRICT[clean];
  }

  // Case-insensitive match
  const lower = clean.toLowerCase();
  for (const [key, list] of Object.entries(THANAS_BY_DISTRICT)) {
    if (key.toLowerCase() === lower) {
      return list;
    }
  }

  // Fallback if district not found
  return [];
}

/**
 * Automatically determine if an address is inside Dhaka city or outside
 */
export function isLocationInsideDhaka(districtName, thanaName = '') {
  if (!districtName) return true;
  const dist = String(districtName).trim().toLowerCase();
  
  if (dist !== 'dhaka' && dist !== 'ঢাকা') {
    return false;
  }

  if (thanaName) {
    const thanaClean = String(thanaName).trim().toLowerCase();
    if (SUB_DHAKA_THANAS.includes(thanaClean)) {
      return false; // Savar, Ashulia, Keraniganj etc. are sub-Dhaka
    }
  }

  return true;
}

/**
 * Automatically calculate delivery charge (70 Tk for Dhaka City, 130 Tk for Outside Dhaka)
 */
export function calculateAutoDeliveryCharge(districtName, thanaName = '') {
  const isInside = isLocationInsideDhaka(districtName, thanaName);
  return {
    deliveryZone: isInside ? 'inside_dhaka' : 'outside_dhaka',
    charge: isInside ? 70 : 130,
    label: isInside ? 'ঢাকা সিটির ভিতরে (Inside Dhaka)' : 'ঢাকার বাইরে (Outside Dhaka)'
  };
}
